import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, sin, cos, mix, smoothstep, time, uniform, PI } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // PALETTE & TOKENS
  // ============================================================================
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#14141a' },
      { at: 1, hex: '#0b0b10' },
    ],
  };

  const typographySpec = config.intent?.visualSpec?.typography ?? config.typography ?? {
    headline: { family: 'Lora', fontSize: 34, fontWeight: 600, letterSpacing: -0.01, lineHeight: 1.15 },
    body: { family: 'JetBrains Mono', fontSize: 13, fontWeight: 400, letterSpacing: 0, lineHeight: 1.5 },
    'cta-label': { family: 'JetBrains Mono', fontSize: 13, fontWeight: 700, letterSpacing: 0.08, lineHeight: 1 },
  };

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Your ledger is empty.', role: 'headline' },
    { text: 'Commissioned pieces and saved references will appear here once you begin.', role: 'body' },
    { text: 'BROWSE THE COLLECTION', role: 'cta-label' },
  ];

  // ============================================================================
  // ROOT GROUP
  // ============================================================================
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.rotation.order = 'XYZ';

  const timelines = [];
  const resources = { textures: [], materials: [], geometries: [], meshes: [] };

  // ============================================================================
  // PANEL GEOMETRY & MATERIAL
  // ============================================================================
  const panelWidth = 3.2;
  const panelHeight = 2.2;
  const panelGeometry = new THREE.PlaneGeometry(panelWidth, panelHeight);
  resources.geometries.push(panelGeometry);

  // TSL-based radial gradient + hairline grid + emissive edge
  // Radial center at (0,0), gradient from #14141a at center to #0b0b10 at edges
  const uv_node = uv();

  // Normalize UV to [-0.5, 0.5] range for distance calc
  const centeredUV = uv_node.sub(0.5);
  const distFromCenter = centeredUV.length();

  // Radial gradient: t = 0 near center, t = 1 at edges (~0.5 dist at edge)
  const radialT = smoothstep(0, 0.7, distFromCenter);

  // Gradient colors (dark center to darker edges for contrast with grid)
  const gradientColor0 = vec3(0.078, 0.078, 0.102); // #14141a
  const gradientColor1 = vec3(0.043, 0.043, 0.063); // #0b0b10
  const gradientBase = mix(gradientColor0, gradientColor1, radialT);

  // Hairline grid at 0.25-unit pitch (1x base unit)
  // Grid in scene coords: need to account for panel size
  const gridScale = 4.0; // 0.25 unit grid -> 4 cycles across panel
  const gridCoords = uv_node.mul(gridScale);
  const gridFract = gridCoords.sub(gridCoords.floor());
  const gridH = smoothstep(0.48, 0.5, gridFract.x).add(smoothstep(0.48, 0.5, gridFract.y));
  const gridAlpha = gridH.mul(0.06); // 6% opacity
  const gridColor = vec3(0.91, 0.925, 0.949); // #e8ecf2

  // Blend: base + grid overlay
  const panelColor = mix(gradientBase, gridColor, gridAlpha);

  // Hairline border #26262f at edges
  const borderDist = smoothstep(0.5, 0.495, Math.max(Math.abs(centeredUV.x), Math.abs(centeredUV.y)));
  const borderColor = vec3(0.149, 0.149, 0.184); // #26262f
  const finalPanelColor = mix(panelColor, borderColor, borderDist.mul(0.006 / 0.5));

  const panelMaterial = new MeshBasicNodeMaterial({
    colorNode: finalPanelColor,
    side: THREE.FrontSide,
    depthWrite: true,
    depthTest: true,
  });
  resources.materials.push(panelMaterial);

  const panelMesh = new THREE.Mesh(panelGeometry, panelMaterial);
  panelMesh.renderOrder = 0;
  root.add(panelMesh);
  resources.meshes.push(panelMesh);

  // ============================================================================
  // GHOST PREVIEW (left, wireframe watch card outline)
  // ============================================================================
  const ghostGroup = new THREE.Group();
  ghostGroup.position.set(-0.7, 0.1, 0.005); // Left of center, slightly raised
  root.add(ghostGroup);

  // Ghost card outline: 1.1w x 1.4h with rounded corners (wireframe effect)
  const ghostCardW = 1.1;
  const ghostCardH = 1.4;
  const cornerRadius = 0.06;
  const ghostStrokeColor = new THREE.Color('#e8ecf2');

  // Wireframe card boundary (use Line segments)
  const ghostCardPoints = [];
  const steps = 8;
  // Top edge
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = -ghostCardW / 2 + t * ghostCardW;
    const y = ghostCardH / 2 - cornerRadius;
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Top-right corner
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = -Math.PI / 2 + t * (Math.PI / 2);
    const x = ghostCardW / 2 - cornerRadius + cornerRadius * Math.cos(angle);
    const y = ghostCardH / 2 - cornerRadius + cornerRadius * Math.sin(angle);
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Right edge
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = ghostCardW / 2 - cornerRadius;
    const y = ghostCardH / 2 - cornerRadius - t * (ghostCardH - 2 * cornerRadius);
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Bottom-right corner
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = 0 + t * (Math.PI / 2);
    const x = ghostCardW / 2 - cornerRadius + cornerRadius * Math.cos(angle);
    const y = -ghostCardH / 2 + cornerRadius + cornerRadius * Math.sin(angle);
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Bottom edge
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = ghostCardW / 2 - t * ghostCardW;
    const y = -ghostCardH / 2 + cornerRadius;
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Bottom-left corner
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = Math.PI / 2 + t * (Math.PI / 2);
    const x = -ghostCardW / 2 + cornerRadius + cornerRadius * Math.cos(angle);
    const y = -ghostCardH / 2 + cornerRadius + cornerRadius * Math.sin(angle);
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Left edge
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = -ghostCardW / 2 + cornerRadius;
    const y = -ghostCardH / 2 + cornerRadius + t * (ghostCardH - 2 * cornerRadius);
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }
  // Top-left corner
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const angle = Math.PI + t * (Math.PI / 2);
    const x = -ghostCardW / 2 + cornerRadius + cornerRadius * Math.cos(angle);
    const y = ghostCardH / 2 - cornerRadius + cornerRadius * Math.sin(angle);
    ghostCardPoints.push(new THREE.Vector3(x, y, 0));
  }

  const ghostLineGeom = new THREE.BufferGeometry();
  ghostLineGeom.setFromPoints(ghostCardPoints);
  const ghostLineMat = new THREE.LineBasicMaterial({ color: ghostStrokeColor, linewidth: 1, transparent: true, opacity: 0.3 });
  const ghostCardLine = new THREE.Line(ghostLineGeom, ghostLineMat);
  ghostCardLine.renderOrder = 1;
  ghostGroup.add(ghostCardLine);
  resources.geometries.push(ghostLineGeom);
  resources.materials.push(ghostLineMat);
  resources.meshes.push(ghostCardLine);

  // Ghost dial circle (0.55 diameter)
  const dialRadius = 0.275;
  const dialSegments = 32;
  const dialGeom = new THREE.BufferGeometry();
  const dialPoints = [];
  for (let i = 0; i <= dialSegments; i++) {
    const angle = (i / dialSegments) * Math.PI * 2;
    dialPoints.push(new THREE.Vector3(dialRadius * Math.cos(angle), dialRadius * Math.sin(angle), 0));
  }
  dialGeom.setFromPoints(dialPoints);
  const dialLineMat = new THREE.LineBasicMaterial({ color: ghostStrokeColor, linewidth: 1, transparent: true, opacity: 0.22 });
  const dialLine = new THREE.Line(dialGeom, dialLineMat);
  dialLine.position.y = 0.15; // Slightly above center
  dialLine.renderOrder = 1;
  ghostGroup.add(dialLine);
  resources.geometries.push(dialGeom);
  resources.materials.push(dialLineMat);
  resources.meshes.push(dialLine);

  // Ghost text bars (two bars, 0.7w x 0.06h at 22% opacity)
  const barWidth = 0.7;
  const barHeight = 0.06;
  const barGeom = new THREE.PlaneGeometry(barWidth, barHeight);
  const barMat = new THREE.MeshBasicMaterial({ color: ghostStrokeColor, transparent: true, opacity: 0.22 });

  const bar1 = new THREE.Mesh(barGeom, barMat);
  bar1.position.y = -0.35;
  bar1.renderOrder = 1;
  ghostGroup.add(bar1);
  resources.meshes.push(bar1);

  const bar2 = new THREE.Mesh(barGeom, barMat);
  bar2.position.y = -0.52;
  bar2.scale.x = 0.6; // Slightly shorter
  bar2.renderOrder = 1;
  ghostGroup.add(bar2);
  resources.meshes.push(bar2);

  resources.materials.push(barMat);
  resources.geometries.push(barGeom);

  // ============================================================================
  // TEXT COLUMN (right of ghost, with padding)
  // ============================================================================
  const textGroup = new THREE.Group();
  textGroup.position.set(0.7, 0.1, 0.01); // Right of ghost
  root.add(textGroup);

  // Headline: "Your ledger is empty."
  const headlineConfig = textItems.find(t => t.role === 'headline');
  const headlineText = headlineConfig?.text ?? 'Your ledger is empty.';
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: typographySpec.headline.fontSize,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: typographySpec.headline.letterSpacing * typographySpec.headline.fontSize,
  });
  headline.position.set(0, 0.35, 0);
  headline.renderOrder = 2;
  textGroup.add(headline);

  // Body: "Commissioned pieces..."
  const bodyConfig = textItems.find(t => t.role === 'body');
  const bodyText = bodyConfig?.text ?? 'Commissioned pieces and saved references will appear here once you begin.';
  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: typographySpec.body.fontSize,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 320,
    letterSpacingPx: typographySpec.body.letterSpacing,
  });
  body.position.set(0, 0.05, 0);
  body.renderOrder = 2;
  textGroup.add(body);

  // ============================================================================
  // CTA BUTTON (below body)
  // ============================================================================
  const ctaWidth = 1.5;
  const ctaHeight = 0.36;
  const ctaGeometry = new THREE.PlaneGeometry(ctaWidth, ctaHeight);
  resources.geometries.push(ctaGeometry);

  // CTA: vertical gradient #ff4450 -> #c1121f with emissive #ff2a38
  const ctaUV = uv();
  const ctaGradientTop = vec3(1.0, 0.267, 0.314); // #ff4450
  const ctaGradientBottom = vec3(0.757, 0.071, 0.122); // #c1121f
  const ctaColor = mix(ctaGradientTop, ctaGradientBottom, ctaUV.y.add(0.5));
  const ctaEmissive = vec3(1.0, 0.165, 0.220); // #ff2a38 intensity 1.5

  const ctaMaterial = new MeshStandardNodeMaterial({
    colorNode: ctaColor,
    emissiveNode: ctaEmissive,
    emissiveIntensity: 1.5,
    metalness: 0,
    roughness: 0.6,
    side: THREE.FrontSide,
    depthWrite: true,
    depthTest: true,
  });
  resources.materials.push(ctaMaterial);

  const ctaMesh = new THREE.Mesh(ctaGeometry, ctaMaterial);
  ctaMesh.position.set(0, -0.52, 0.01);
  ctaMesh.renderOrder = 2;
  textGroup.add(ctaMesh);
  resources.meshes.push(ctaMesh);

  // CTA label text
  const ctaLabelConfig = textItems.find(t => t.role === 'cta-label');
  const ctaLabelText = ctaLabelConfig?.text ?? 'BROWSE THE COLLECTION';
  const ctaLabel = ctx.fontAtlas.createText(ctaLabelText, {
    fontSize: typographySpec['cta-label'].fontSize,
    color: colors.ink,
    align: 'center',
    letterSpacingPx: typographySpec['cta-label'].letterSpacing + 0.08,
  });
  ctaLabel.position.set(0, -0.52, 0.02);
  ctaLabel.renderOrder = 3;
  textGroup.add(ctaLabel);

  // ============================================================================
  // ANIMATIONS
  // ============================================================================
  // Ghost group breathing: opacity 0.24 -> 0.34 over 2400ms cubic-bezier(0.445,0.05,0.55,0.95)
  const ghostTL = gsap.timeline({ repeat: -1, yoyo: true });
  ghostTL.to(ghostGroup, {
    opacity: 0.34,
    duration: 2.4,
    ease: 'power2.inOut',
  }, 0);
  timelines.push(ghostTL);
  ghostGroup.userData.timeline = ghostTL;

  // Panel + text fade-up: opacity 0 -> 1, y +0.2 -> 0 over 500ms cubic-bezier(0.25,0.46,0.45,0.94)
  panelMesh.userData.initialOpacity = 1;
  textGroup.userData.initialOpacity = 1;

  root.position.y = 0.2;
  root.opacity = 0;

  const mountTL = gsap.timeline();
  mountTL.to(root, {
    opacity: 1,
    y: 0,
    duration: 0.5,
    ease: [0.25, 0.46, 0.45, 0.94],
  });
  timelines.push(mountTL);

  // CTA press interaction (scale 1.0 -> 0.97 on click)
  ctaMesh.userData.handlers = {
    click: () => {
      gsap.to(ctaMesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: [0.175, 0.885, 0.32, 1.275],
        yoyo: true,
        repeat: 1,
      });
      // Emit navigate event
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  // ============================================================================
  // CLEANUP
  // ============================================================================
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    resources.meshes.forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) {
        if (Array.isArray(m.material)) m.material.forEach(mat => mat.dispose());
        else m.material.dispose();
      }
    });
    resources.geometries.forEach(g => g.dispose());
    resources.materials.forEach(m => m.dispose());
    resources.textures.forEach(t => t.dispose());
  };

  return root;
}
